action.code:
size_t tab_size = (ZU(1) << ckh->lg_curbuckets) * (ZU(1) << LG_CKH_BUCKET_CELLS);
while (*tabind < tab_size) {
    ckhc_t *cell = &ckh->tab[*tabind];
    if (cell->key != NULL) {
        if (key != NULL) {
            *key = cell->key;
        }
        if (data != NULL) {
            *data = cell->data;
        }
        (*tabind)++;
        return false;
    }
    (*tabind)++;
}
return true;

